record.field:
website = env.ref('team_sports_club.website_industry')
MARK = '__EXPORT_FILTER_XMLID__'
for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]):
    arch = view.arch_db or ''
    if MARK not in arch:
        continue
    new_arch = arch
    while MARK in new_arch:
        start = new_arch.index(MARK)
        end = new_arch.index(MARK, start + len(MARK)) + len(MARK)
        xmlid = new_arch[start + len(MARK):end - len(MARK)]
        try:
            resolved = str(env.ref(xmlid).id)
        except ValueError:
            resolved = '0'
        new_arch = new_arch[:start] + resolved + new_arch[end:]
    view.write({'arch_db': new_arch})

# The builder exports hrefs containing database ids (/event/season-2026-2027-8,
# /partners/grade/first-team-4). Those ids differ on every install, so the pages
# ship *tokens* instead and we swap in the real website_url here. A plain string
# swap on the arch also reaches the footer, whose markup is t-ignore'd and so
# could never resolve a dynamic t-attf-href.
tokens = {
    '*season_pass_event*': 'team_sports_club.event_event_8',        # Season 2026-2027
    '*first_team_grade*': 'team_sports_club.res_partner_grade_9',   # D1
    '*women_team_grade*': 'team_sports_club.res_partner_grade_16',  # Women First Team
}
urls = {}
for token, xml_id in tokens.items():
    record = env.ref(xml_id, raise_if_not_found=False)
    if record and record.website_url:
        urls[token] = record.website_url

# event.tag has no real website_url (it stays on the mixin's default '#'), the
# footer instead links to the /event listing filtered on the tag, built from its slug.
tag_tokens = {
    '*single_match_ticket_tag*': 'team_sports_club.event_tag_1',  # Single Match Ticket
    '*season_ticket_tag*': 'team_sports_club.event_tag_2',        # Season Ticket
    '*youth_camp_tag*': 'team_sports_club.event_tag_3',           # Youth Camp
}
for token, xml_id in tag_tokens.items():
    tag = env.ref(xml_id, raise_if_not_found=False)
    if tag:
        urls[token] = '/event/tags/%s' % env['ir.http']._slug(tag)

views = [
    'team_sports_club.view_page_home',
    'team_sports_club.template_footer_mega_links',
]
for xml_id in views:
    view = env.ref(xml_id, raise_if_not_found=False)
    if not view:
        continue
    arch = view.arch
    for token, url in urls.items():
        arch = arch.replace(token, url)
    if arch != view.arch:
        view.write({'arch': arch})
